arguments.command:
cat > /tmp/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *[Uu]sername*) printf '%s' "x-access-token" ;;
  *[Pp]assword*) printf '%s' "${GITHUB_TOKEN}" ;;
  *) printf '%s' "" ;;
esac
EOF
chmod +x /tmp/askpass.sh
cd /tmp/friends-main && GIT_ASKPASS=/tmp/askpass.sh git push origin ross-main:main 2>&1 | tail -3; git log --oneline origin/main -1
